// ===================== Qui l'a vraiment dit ? =====================
// Citations célèbres. statut : « authentique » (bien attribuée), « deformee » (l'original est différent),
// « apocryphe » (aucune trace chez l'auteur supposé). Vérifiées dans les œuvres, Wikipédia,
// Wikiquote ou Quote Investigator.
// Niveaux : 1, citations dont l'attribution est très connue ou très discutée ; 2, citations courantes dont
// l'origine l'est moins ; 3, attributions erronées tenaces ou citations authentiques peu connues.
const CITATIONS = [
  { id: "voltaire", niveau: 2, texte: "Je ne suis pas d'accord avec ce que vous dites, mais je me battrai jusqu'à la mort pour que vous ayez le droit de le dire.", auteur: "Voltaire", statut: "apocryphe",
    explication: "La phrase a été écrite en 1906 par la biographe anglaise Evelyn Beatrice Hall, dans « The Friends of Voltaire », pour résumer l'attitude de Voltaire, pas pour le citer." },
  { id: "einstein-folie", niveau: 2, texte: "La folie, c'est de faire toujours la même chose et de s'attendre à un résultat différent.", auteur: "Albert Einstein", statut: "apocryphe",
    explication: "Rien ne l'atteste chez Einstein. Les premières traces datent de 1981, dans des groupes d'entraide (Al-Anon, Narcotiques anonymes) ; le recueil de référence « The Ultimate Quotable Einstein » la classe parmi les fausses attributions." },
  { id: "henri4", niveau: 2, texte: "Paris vaut bien une messe.", auteur: "Henri IV", statut: "apocryphe",
    explication: "Le mot résume sa conversion au catholicisme en 1593, nécessaire pour régner, mais les historiens jugent l'attribution apocryphe." },
  { id: "galilee", niveau: 1, texte: "Et pourtant, elle tourne.", auteur: "Galilée, après son procès (1633)", statut: "apocryphe",
    explication: "La phrase apparaît pour la première fois dans un livre de Giuseppe Baretti en 1757, plus d'un siècle après le procès. Rien n'indique que Galilée l'ait prononcée." },
  { id: "louis14", niveau: 1, texte: "L'État, c'est moi.", auteur: "Louis XIV", statut: "apocryphe",
    explication: "Elle n'apparaît pas dans les registres du parlement où elle aurait été prononcée en 1655 ; la formule est publiée en 1818 par l'historien Pierre-Édouard Lémontey." },
  { id: "ford", niveau: 2, texte: "Si j'avais demandé aux gens ce qu'ils voulaient, ils m'auraient répondu : des chevaux plus rapides.", auteur: "Henry Ford", statut: "apocryphe",
    explication: "On n'en trouve aucune trace avant 1999-2001, plus de cinquante ans après la mort de Ford (1947). Le musée Henry Ford lui-même ne l'a jamais trouvée dans ses archives." },
  { id: "darwin", niveau: 3, texte: "Ce n'est pas le plus fort de l'espèce qui survit, ni le plus intelligent, mais celui qui s'adapte le mieux au changement.", auteur: "Charles Darwin", statut: "apocryphe",
    explication: "C'est une paraphrase écrite en 1963 par Leon Megginson, professeur de gestion, pour résumer Darwin à sa façon. Elle ne figure dans aucun texte de Darwin." },
  { id: "burke", niveau: 3, texte: "Pour triompher, le mal n'a besoin que de l'inaction des gens de bien.", auteur: "Edmund Burke", statut: "apocryphe",
    explication: "Introuvable dans les écrits de Burke : la formule apparaît au XXe siècle et lui a été attribuée après coup." },
  { id: "malraux", niveau: 3, texte: "Le XXIe siècle sera religieux ou ne sera pas.", auteur: "André Malraux", statut: "apocryphe",
    explication: "Malraux a plusieurs fois démenti l'avoir prononcée. André Frossard affirmait l'avoir entendue sous une autre forme : « Le XXIe siècle sera mystique ou ne sera pas »." },
  { id: "statistiques", niveau: 3, texte: "Il y a trois sortes de mensonges : les mensonges, les sacrés mensonges et les statistiques.", auteur: "Benjamin Disraeli", statut: "apocryphe",
    explication: "Mark Twain l'attribuait à Disraeli, mais la phrase ne figure dans aucun de ses écrits et n'apparaît qu'après sa mort. Son auteur reste inconnu." },
  // Ajoutée le 18 novembre 2026 : « depuis » (premier jour d'apparition) pour ne pas rebattre les cartes déjà jouées
  { id: "impossible", niveau: 2, depuis: 20776, texte: "Impossible n'est pas français.", auteur: "Napoléon", statut: "deformee",
    explication: "Le 9 juillet 1813, à Dresde, Napoléon répond au général Lemarois, gouverneur de Magdebourg, qui jugeait impossible d'envoyer de l'avoine : « “Ce n'est pas possible”, m'écrivez-vous : cela n'est pas français. » La formule courte, devenue proverbe, résume la lettre (Correspondance de Napoléon Ier, tome XXV, lettre n° 20256)." },
  { id: "gandhi", niveau: 3, texte: "Sois le changement que tu veux voir dans le monde.", auteur: "Gandhi", statut: "deformee",
    explication: "La formule ne figure pas dans ses écrits et n'apparaît pas avant les années 1970. Le passage le plus proche, de 1913, dit : « Si nous pouvions nous changer nous-mêmes, les tendances du monde changeraient aussi. » La version courte efface l'idée que changement personnel et changement social vont ensemble." },
  { id: "watson", niveau: 1, texte: "Élémentaire, mon cher Watson.", auteur: "Sherlock Holmes, chez Conan Doyle", statut: "deformee",
    explication: "La phrase exacte ne figure dans aucun récit de Conan Doyle : Holmes dit « Élémentaire » ou « mon cher Watson », jamais les deux ensemble. Elle apparaît chez d'autres auteurs au début du XXe siècle et se répand avec le cinéma." },
  { id: "vador", niveau: 1, texte: "Luke, je suis ton père.", auteur: "Dark Vador, « L'Empire contre-attaque » (1980)", statut: "deformee",
    explication: "La réplique est : « Non, je suis ton père. » Le prénom ajouté est un faux souvenir très répandu." },
  { id: "casablanca", niveau: 1, texte: "Joue-la encore, Sam.", auteur: "Humphrey Bogart, « Casablanca » (1942)", statut: "deformee",
    explication: "Cette phrase n'est jamais prononcée dans le film. Ilsa demande : « Joue-la, Sam » ; le « encore » a été ajouté par la mémoire collective, puis repris comme titre d'une pièce de Woody Allen." },
  { id: "lavoisier", niveau: 1, texte: "Rien ne se perd, rien ne se crée, tout se transforme.", auteur: "Antoine Lavoisier", statut: "deformee",
    explication: "Lavoisier écrit en 1789 que « rien ne se crée, ni dans les opérations de l'art, ni dans celles de la nature ». La maxime est une reformulation, d'ailleurs proche d'une idée du philosophe grec Anaxagore." },
  { id: "machiavel", niveau: 2, texte: "La fin justifie les moyens.", auteur: "Machiavel", statut: "deformee",
    explication: "La formule n'apparaît ni dans « Le Prince » ni dans ses autres œuvres : c'est un résumé tardif et simplificateur. Au chapitre XVIII, il écrit plutôt que, pour juger les actions des princes, on regarde le résultat." },
  { id: "camus", niveau: 3, texte: "Mal nommer les choses, c'est ajouter au malheur du monde.", auteur: "Albert Camus", statut: "deformee",
    explication: "Camus a écrit en 1944 : « Mal nommer un objet, c'est ajouter au malheur de ce monde », dans un article où il commentait les idées du philosophe Brice Parain." },
  { id: "socrate", niveau: 2, texte: "Je sais que je ne sais rien.", auteur: "Socrate", statut: "deformee",
    explication: "La formule ne figure pas telle quelle chez Platon. Dans l'« Apologie », Socrate dit qu'il est plus sage qu'un autre en ceci qu'il ne croit pas savoir ce qu'il ne sait pas." },
  { id: "churchill", niveau: 2, texte: "La démocratie est le pire des régimes, à l'exception de tous les autres.", auteur: "Winston Churchill", statut: "authentique",
    explication: "Churchill l'a bien dite à la Chambre des communes, en novembre 1947… en la présentant comme un mot déjà connu : « On a dit que la démocratie est la pire forme de gouvernement… » Son véritable auteur reste inconnu." },
  { id: "russell", niveau: 3, texte: "Le problème de ce monde, c'est que les imbéciles sont sûrs d'eux, alors que les gens intelligents sont pleins de doutes.", auteur: "Bertrand Russell", statut: "authentique",
    explication: "Russell l'écrit en 1933, dans un article sur la montée du nazisme : « les stupides sont sûrs d'eux, tandis que les intelligents sont pleins de doutes ». On la rapproche souvent de l'effet Dunning-Kruger, décrit en 1999." },
  { id: "newton", niveau: 1, texte: "Si j'ai vu plus loin, c'est en me tenant sur les épaules de géants.", auteur: "Isaac Newton", statut: "authentique",
    explication: "Newton l'écrit en 1675 dans une lettre à Robert Hooke. L'image est bien plus ancienne : Jean de Salisbury l'attribue en 1159 à Bernard de Chartres." },
  { id: "marx", niveau: 1, texte: "La religion est l'opium du peuple.", auteur: "Karl Marx", statut: "authentique",
    explication: "Elle figure dans l'introduction à la « Critique de la philosophie du droit de Hegel » (écrite en 1843, publiée en 1844), juste après : « La religion est le soupir de la créature opprimée, l'âme d'un monde sans cœur »." },
  { id: "kant", niveau: 2, texte: "Sapere aude ! Aie le courage de te servir de ton propre entendement.", auteur: "Emmanuel Kant", statut: "authentique",
    explication: "C'est la devise des Lumières selon Kant, dans « Qu'est-ce que les Lumières ? » (1784). Les deux premiers mots viennent du poète latin Horace." },
  { id: "feynman", niveau: 3, texte: "Le premier principe est de ne pas se tromper soi-même, et vous êtes la personne la plus facile à tromper.", auteur: "Richard Feynman", statut: "authentique",
    explication: "Feynman le dit en 1974 dans son discours aux diplômés du California Institute of Technology, publié sous le titre « Cargo Cult Science » : une mise en garde contre les études qui confirment ce qu'on voulait trouver." },
  { id: "hume", niveau: 3, texte: "Le sage proportionne sa croyance aux preuves.", auteur: "David Hume", statut: "authentique",
    explication: "« A wise man proportions his belief to the evidence » : « Enquête sur l'entendement humain » (1748), dans le chapitre sur les miracles." },
  { id: "descartes", niveau: 1, texte: "Je pense, donc je suis.", auteur: "René Descartes", statut: "authentique",
    explication: "En français dans le « Discours de la méthode » (1637), puis en latin, « Cogito, ergo sum », dans les « Principes de la philosophie » (1644)." },
  { id: "pascal", niveau: 1, texte: "Le cœur a ses raisons que la raison ne connaît point.", auteur: "Blaise Pascal", statut: "authentique",
    explication: "Elle figure dans les « Pensées », publiées en 1670, après sa mort." },
  { id: "sartre", niveau: 1, texte: "L'enfer, c'est les autres.", auteur: "Jean-Paul Sartre", statut: "authentique",
    explication: "La réplique figure dans « Huis clos » (1944). Elle est souvent comprise de travers : Sartre a expliqué qu'elle décrit des rapports avec autrui faussés, pas les relations humaines en général." },
  { id: "montaigne", niveau: 1, texte: "Que sais-je ?", auteur: "Michel de Montaigne", statut: "authentique",
    explication: "C'est sa devise, dans les « Essais » (livre II, chapitre 12) : l'expression d'un doute sceptique sur la portée de nos connaissances." },
  { id: "rabelais", niveau: 2, texte: "Science sans conscience n'est que ruine de l'âme.", auteur: "François Rabelais", statut: "authentique",
    explication: "La phrase figure dans « Pantagruel » (1532), dans une lettre de Gargantua à son fils." },
  { id: "einstein-des", niveau: 2, texte: "Dieu ne joue pas aux dés.", auteur: "Albert Einstein", statut: "authentique",
    explication: "Authentique sur le fond : dans une lettre à Max Born de 1926, Einstein écrit être convaincu que « Lui ne joue pas aux dés », pour contester le caractère probabiliste de la mécanique quantique." },
  { id: "nietzsche", niveau: 2, texte: "Ce qui ne me tue pas me rend plus fort.", auteur: "Friedrich Nietzsche", statut: "authentique",
    explication: "Elle figure dans « Crépuscule des idoles » (1888), parmi les « Maximes et pointes »." },
  { id: "candide", niveau: 1, texte: "Il faut cultiver notre jardin.", auteur: "Voltaire", statut: "authentique",
    explication: "C'est la dernière phrase de « Candide » (1759), en réponse à l'optimisme du philosophe Pangloss." },
  { id: "boileau", niveau: 1, texte: "Ce que l'on conçoit bien s'énonce clairement.", auteur: "Nicolas Boileau", statut: "authentique",
    explication: "Elle figure dans « L'Art poétique » (1674), suivie de : « Et les mots pour le dire arrivent aisément »." },
  // Ajouts pour la progression : attributions vérifiées sur Wikiquote, Wikisource et Quote Investigator
  { id: "lafontaine", niveau: 1, texte: "La raison du plus fort est toujours la meilleure.", auteur: "Jean de La Fontaine", statut: "authentique",
    explication: "Premier vers de la fable « Le Loup et l'Agneau » (1668). La Fontaine ne l'approuve pas : il constate, et la fable le montre." },
  { id: "beauvoir", niveau: 1, texte: "On ne naît pas femme : on le devient.", auteur: "Simone de Beauvoir", statut: "authentique",
    explication: "« Le Deuxième Sexe » (1949)." },
  { id: "pascal-roseau", niveau: 2, texte: "L'homme n'est qu'un roseau, le plus faible de la nature ; mais c'est un roseau pensant.", auteur: "Blaise Pascal", statut: "authentique",
    explication: "« Pensées », publiées après sa mort (1670). On la cite souvent raccourcie : « L'homme est un roseau pensant »." },
  { id: "descartes-bon-sens", niveau: 2, texte: "Le bon sens est la chose du monde la mieux partagée.", auteur: "René Descartes", statut: "authentique",
    explication: "Première phrase du « Discours de la méthode » (1637). La suite est ironique : chacun pense en être si bien pourvu qu'il n'en désire pas davantage." },
  { id: "rousseau", niveau: 2, texte: "L'homme est né libre, et partout il est dans les fers.", auteur: "Jean-Jacques Rousseau", statut: "authentique",
    explication: "« Du contrat social » (1762), livre I." },
  { id: "twain", niveau: 2, texte: "Les rumeurs de ma mort sont très exagérées.", auteur: "Mark Twain", statut: "deformee",
    explication: "En 1897, apprenant qu'un journal le disait mourant, il écrit : « Le bruit de ma mort était une exagération » ; c'était un cousin qui avait été malade à Londres. La version courante enjolive la phrase." },
  { id: "einstein-imagination", niveau: 2, texte: "L'imagination est plus importante que le savoir.", auteur: "Albert Einstein", statut: "authentique",
    explication: "Entretien avec le journaliste George Sylvester Viereck, en 1929 : « L'imagination est plus importante que le savoir. Le savoir est limité. L'imagination embrasse le monde. »" },
  { id: "einstein-abeilles", niveau: 3, texte: "Si l'abeille venait à disparaître, l'homme n'aurait plus que quatre années à vivre.", auteur: "Albert Einstein", statut: "apocryphe",
    explication: "Aucune trace dans ses écrits. Un lien entre Einstein et la disparition des abeilles apparaît dans une revue d'apiculture canadienne en 1941 ; le délai de quatre ans, dans un magazine français en 1965, dix ans après sa mort." },
  { id: "einstein-infini", niveau: 3, texte: "Deux choses sont infinies : l'univers et la bêtise humaine ; mais pour l'univers, je n'en suis pas certain.", auteur: "Albert Einstein", statut: "apocryphe",
    explication: "On ne la trouve dans aucun écrit d'Einstein. Le psychothérapeute Fritz Perls l'attribuait dans les années 1940 à « un grand astronome », puis, à partir de 1969, à Einstein." },
  { id: "churchill-succes", niveau: 3, texte: "Le succès, c'est d'aller d'échec en échec sans perdre son enthousiasme.", auteur: "Winston Churchill", statut: "apocryphe",
    explication: "Introuvable dans ses discours et ses écrits. Richard Langworth, qui a réuni ses citations, la classe parmi les fausses attributions." },
  { id: "terre-enfants", niveau: 3, texte: "Nous n'héritons pas de la terre de nos ancêtres, nous l'empruntons à nos enfants.", auteur: "Antoine de Saint-Exupéry", statut: "apocryphe",
    explication: "Aucune trace chez Saint-Exupéry, mort en 1944. La plus ancienne formulation proche est celle de l'écrivain américain Wendell Berry, en 1971." },
  { id: "platon-guerre", niveau: 3, texte: "Seuls les morts ont vu la fin de la guerre.", auteur: "Platon", statut: "apocryphe",
    explication: "La phrase est du philosophe George Santayana, dans « Soliloquies in England » (1922). Elle ne figure dans aucun dialogue de Platon." },
  { id: "hume-passions", niveau: 3, texte: "La raison est, et ne doit être, que l'esclave des passions.", auteur: "David Hume", statut: "authentique",
    explication: "« Traité de la nature humaine » (1739-1740), livre II : pour Hume, la raison éclaire les moyens, mais ce sont les désirs qui fixent les fins." },
  { id: "pasteur-hasard", niveau: 3, texte: "Le hasard ne favorise que les esprits préparés.", auteur: "Louis Pasteur", statut: "authentique",
    explication: "Discours prononcé à Douai en 1854, pour l'installation de la faculté des sciences de Lille : « Dans les champs de l'observation, le hasard ne favorise que les esprits préparés. »" },
  { id: "cesar", niveau: 1, texte: "Je suis venu, j'ai vu, j'ai vaincu.", auteur: "Jules César", statut: "authentique",
    explication: "« Veni, vidi, vici » : selon Suétone (« Vie de César », 37), la formule était inscrite sur un écriteau porté lors du triomphe qui célébrait sa victoire dans le Pont, en Asie Mineure, pour dire la rapidité de cette victoire." },
  { id: "hamlet", niveau: 1, texte: "Être ou ne pas être, telle est la question.", auteur: "William Shakespeare", statut: "authentique",
    explication: "« To be, or not to be, that is the question » : début du monologue d'Hamlet, acte III, scène 1." },
  { id: "franklin-temps", niveau: 2, texte: "Le temps, c'est de l'argent.", auteur: "Benjamin Franklin", statut: "authentique",
    explication: "« Remember that time is money » : « Conseils à un jeune artisan » (1748). Franklin a popularisé la maxime ; elle circulait peut-être déjà avant lui." },
  { id: "santayana-passe", niveau: 2, texte: "Ceux qui ne peuvent se souvenir du passé sont condamnés à le répéter.", auteur: "George Santayana", statut: "authentique",
    explication: "« La Vie de la raison », premier volume (1905). La phrase est souvent prêtée à Churchill, qui l'a paraphrasée devant la Chambre des communes en 1948." },
  { id: "sagan-preuves", niveau: 2, texte: "Les affirmations extraordinaires exigent des preuves extraordinaires.", auteur: "Carl Sagan", statut: "authentique",
    explication: "Il l'a dite dès 1977 et écrite dans « Broca's Brain » (1979). L'idée est plus ancienne : Laplace écrivait déjà que « plus un fait est extraordinaire, plus il a besoin d'être appuyé de fortes preuves »." },
  { id: "edison-genie", niveau: 2, texte: "Le génie, c'est 1 % d'inspiration et 99 % de transpiration.", auteur: "Thomas Edison", statut: "authentique",
    explication: "Edison s'en est réclamé dans une lettre de 1927 ; des versions plus anciennes de ses propos, dès 1898, donnaient 2 % et 98 %." },
  { id: "twain-mensonge", niveau: 3, texte: "Un mensonge peut faire le tour de la Terre pendant que la vérité met ses chaussures.", auteur: "Mark Twain", statut: "apocryphe",
    explication: "Aucune trace dans ses écrits : l'attribution apparaît vers 1919-1921, après sa mort. L'idée remonte au moins à Jonathan Swift, en 1710 : « Le mensonge vole, et la vérité le suit en boitant. »" },
  // Ajouts du 22 novembre 2026, contre-vérifiés (agent verificateur-sources) ; « depuis » : 24 novembre.
  // Sources lues le 22 novembre 2026 : https://www.margaretthatcher.org/document/106689
  { id: "thatcher-societe", depuis: 20781, niveau: 3, texte: "La société, ça n'existe pas.", auteur: "Margaret Thatcher", statut: "authentique",
    explication: "Entretien au magazine « Woman's Own », à Downing Street, le 23 septembre 1987 : « There is no such thing as society. » Elle vise l'idée que l'État doit tout régler, et parle aussitôt d'une « tapisserie vivante d'hommes et de femmes » dont chacun doit aider les plus malheureux." },
  // Sources lues le 22 novembre 2026 : https://www.elysee.fr/francois-mitterrand/1995/01/17/discours-de-m-francois-mitterrand-president-de-la-republique-sur-le-programme-de-la-presidence-francaise-de-lunion-europeenne-notamment-en-matiere-delargissement-dunion-economique-et-monetaire-dorganisation-de-leurope-sociale-didentite-cultu
  { id: "mitterrand-nationalisme", depuis: 20781, niveau: 2, texte: "Le nationalisme, c'est la guerre.", auteur: "François Mitterrand", statut: "authentique",
    explication: "Devant le Parlement européen, à Strasbourg, le 17 janvier 1995, après avoir raconté sa captivité en Allemagne : « il faut vaincre notre histoire et pourtant si on ne la vainc pas, il faut savoir qu'une règle s'imposera […] : le nationalisme, c'est la guerre ! »" },
  // Sources lues le 22 novembre 2026 : https://www.marxists.org/reference/archive/mao/selected-works/volume-2/mswv2_12.htm
  { id: "mao-fusil", depuis: 20781, niveau: 2, texte: "Le pouvoir est au bout du fusil.", auteur: "Mao Zedong", statut: "authentique",
    explication: "« Problèmes de la guerre et de la stratégie », 6 novembre 1938 : « Le pouvoir politique est au bout du fusil. » La phrase qui suit est moins citée : « Notre principe, c'est que le Parti commande au fusil, et que le fusil ne doit jamais commander au Parti. »" },
  // Vérifié via http://web.archive.org/web/20220706044626/http://db.nelsonmandela.org/speeches/pub_view.asp?pg=item&ItemID=NMS909 ; https://archive.nelsonmandela.org/index.php/za-com-mr-s-909 ; https://barrypopik.com/blog/education_is_the_most_powerful_weapon
  { id: "mandela-education", depuis: 20781, niveau: 2, texte: "L'éducation est l'arme la plus puissante pour changer le monde.", auteur: "Nelson Mandela", statut: "authentique",
    explication: "Elle a tout d'une phrase de poster, mais elle est de lui : discours au lancement du réseau éducatif Mindset, à l'université du Witwatersrand, à Johannesburg, le 16 juillet 2003 : « L'éducation est l'arme la plus puissante que nous puissions utiliser pour changer le monde »." },
  // Vérifié via https://kinginstitute.stanford.edu/our-god-marching ; https://quoteinvestigator.com/2012/11/15/arc-of-universe/
  { id: "king-arc", depuis: 20781, niveau: 3, texte: "L'arc de l'univers moral est long, mais il penche vers la justice.", auteur: "Martin Luther King", statut: "authentique",
    explication: "King l'a bien dite, notamment à Montgomery, en Alabama, le 25 mars 1965 : « Combien de temps ? Pas longtemps, car l'arc de l'univers moral est long, mais il penche vers la justice. » Mais il citait : dès 1958, il la mettait entre guillemets. L'image vient d'un sermon du pasteur abolitionniste Theodore Parker, publié en 1853." },
  // Sources lues le 22 novembre 2026 : https://it.wikisource.org/wiki/Il_Saggiatore/6
  { id: "galilee-livre", depuis: 20781, niveau: 3, texte: "Le grand livre de l'univers est écrit en langue mathématique.", auteur: "Galilée", statut: "authentique",
    explication: "« L'Essayeur » (« Il Saggiatore », 1623) : la philosophie « est écrite dans ce très grand livre continuellement ouvert devant nos yeux (je veux dire l'univers) », et « il est écrit en langue mathématique ». Galilée répond à un adversaire qui croit qu'il faut toujours s'appuyer sur l'opinion d'un auteur célèbre." },
  // Sources lues le 22 novembre 2026 : https://zh.wikisource.org/wiki/道德經_(王弼本
  { id: "laozi-pas", depuis: 20781, niveau: 2, texte: "Un voyage de mille lieues commence par un premier pas.", auteur: "Lao-tseu", statut: "authentique",
    explication: "« Tao-tö-king », le livre que la tradition lui attribue, chapitre 64, mot à mot : « Le voyage de mille li commence sous les pieds. » Stanislas Julien traduisait en 1842 : « un voyage de mille lis a commencé par un pas ». Le passage conseille d'agir sur les choses avant qu'elles n'existent, de mettre en ordre avant le désordre : l'arbre le plus large est né d'une pousse fine comme un poil." },
  // Sources lues le 22 novembre 2026 : https://www.marxists.org/reference/archive/deng-xiaoping/1962/190.htm
  { id: "deng-chat", depuis: 20781, niveau: 2, texte: "Peu importe que le chat soit blanc ou noir, pourvu qu'il attrape les souris.", auteur: "Deng Xiaoping", statut: "deformee",
    explication: "Le 7 juillet 1962, devant la Ligue de la jeunesse communiste, Deng reprend un proverbe du Sichuan que citait souvent Liu Bocheng : « Peu importe que le chat soit jaune ou noir, pourvu qu'il attrape les souris. » Le chat jaune est devenu blanc en route ; l'idée reste : juger une organisation agricole à ses résultats." },
  // Vérifié via https://quoteinvestigator.com/2017/09/25/progress/ ; https://en.wikipedia.org/wiki/Planck%27s_principle
  { id: "planck-funerailles", depuis: 20781, niveau: 3, texte: "La science progresse d'enterrement en enterrement.", auteur: "Max Planck", statut: "deformee",
    explication: "Planck écrit, dans son autobiographie scientifique, qu'une vérité scientifique nouvelle ne triomphe pas en convainquant ses adversaires, mais parce que ceux-ci finissent par mourir et qu'une nouvelle génération grandit en la connaissant. La formule courte, plus frappante, est une reprise plus tardive." },
  // Sources lues le 22 novembre 2026 : https://zh.wikisource.org/wiki/孫子兵法
  { id: "sunzi", depuis: 20781, niveau: 2, texte: "Connais ton ennemi et connais-toi toi-même.", auteur: "Sun Tzu", statut: "authentique",
    explication: "« L'Art de la guerre », chapitre III. La suite varie selon les traductions : celle du jésuite Amiot, qui a fait connaître le livre en France au XVIIIe siècle, promet « cent fois vous serez victorieux », alors que le texte chinois dit seulement qu'on « ne sera pas en péril en cent combats ». Qui se connaît sans connaître l'autre gagne une fois sur deux ; qui ne connaît ni l'un ni l'autre est en péril à chaque combat." },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/2017/08/13/stages/
  { id: "gandhi-ignorer", depuis: 20781, niveau: 2, texte: "D'abord ils vous ignorent, puis ils se moquent de vous, puis ils vous combattent, et puis vous gagnez.", auteur: "Gandhi", statut: "apocryphe",
    explication: "Rien ne l'atteste chez Gandhi : le lien avec lui n'apparaît qu'en 1982. La gradation vient d'un syndicaliste américain, Nicholas Klein, en 1918 : « D'abord ils vous ignorent. Puis ils vous ridiculisent. Puis ils vous attaquent et veulent vous brûler. Et puis ils vous élèvent des monuments. »" },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/2013/02/24/truth-revolutionary/
  { id: "orwell-verite", depuis: 20781, niveau: 3, texte: "En des temps de tromperie universelle, dire la vérité est un acte révolutionnaire.", auteur: "George Orwell", statut: "apocryphe",
    explication: "Personne ne l'a trouvée dans son œuvre. La plus ancienne trace connue est une épigraphe de 1982, sans le mot « universelle », dans un livre australien sur le commerce de l'uranium ; Orwell était mort en 1950." },
  // Sources lues le 22 novembre 2026 : http://web.archive.org/web/20260628173441/https://www.nelsonmandela.org/news/entry/deepest-fear-quote-not-mr-mandelas/ ; https://quoteinvestigator.com/2019/06/30/deepest/
  { id: "mandela-peur", depuis: 20781, niveau: 3, texte: "Notre peur la plus profonde n'est pas d'être insuffisants, c'est d'être puissants au-delà de toute mesure.", auteur: "Nelson Mandela, discours d'investiture (1994)", statut: "apocryphe",
    explication: "Le passage vient d'un livre de l'Américaine Marianne Williamson, « A Return to Love » (1992). La Fondation Nelson Mandela a précisé en 2007 qu'il ne figure dans aucun des trois discours prononcés lors de son investiture." },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/?p=436269 ; https://barrypopik.com/blog/useful_idiot
  { id: "lenine-idiots", depuis: 20781, niveau: 2, texte: "Les idiots utiles de l'Occident.", auteur: "Lénine", statut: "apocryphe",
    explication: "On ne la trouve dans aucun texte connu de Lénine. L'expression circule dans les années 1940 pour désigner les démocrates qui font le jeu des communistes ; elle n'est prêtée à Lénine, mort en 1924, que plus tard." },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/2010/07/08/laws-sausages/
  { id: "bismarck-saucisses", depuis: 20781, niveau: 3, texte: "Les lois, c'est comme les saucisses : mieux vaut ne pas voir comment on les fait.", auteur: "Otto von Bismarck", statut: "apocryphe",
    explication: "Elle est attribuée en 1869 au poète américain John Godfrey Saxe : « Les lois, comme les saucisses, cessent d'inspirer le respect à mesure qu'on sait comment elles sont faites. » Le nom de Bismarck n'y est accolé que dans les années 1930." },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/2014/09/02/job-love/
  { id: "confucius-travail", depuis: 20781, niveau: 2, texte: "Choisis un travail que tu aimes, et tu n'auras pas à travailler un seul jour de ta vie.", auteur: "Confucius", statut: "apocryphe",
    explication: "Rien de tel chez Confucius. La plus ancienne trace connue date de 1982, dans le magazine des anciens élèves de Princeton : un professeur de philosophie la tenait d'« un ancien ». Elle n'est prêtée à Confucius que plus tard." },
  // Sources lues le 22 novembre 2026 : https://quoteinvestigator.com/2026/07/10/democracy-five/ ; https://richardlangworth.com/voter
  { id: "churchill-electeur", depuis: 20781, niveau: 3, texte: "Le meilleur argument contre la démocratie, c'est une conversation de cinq minutes avec l'électeur moyen.", auteur: "Winston Churchill", statut: "apocryphe",
    explication: "Introuvable dans ses discours et ses écrits : Richard Langworth, spécialiste de ses citations, la classe parmi les fausses attributions. Churchill disait plutôt, aux Communes en octobre 1944, qu'à la base de tous les hommages rendus à la démocratie il y a « le petit homme qui entre dans le petit isoloir, avec un petit crayon, et trace une petite croix sur un petit bout de papier », et qu'aucun discours ne saurait atténuer l'importance de ce geste." },
  // Sources lues le 22 novembre 2026 : https://archive.org/details/in.ernet.dli.2015.264687
  { id: "aristote-habitude", depuis: 20781, niveau: 3, texte: "Nous sommes ce que nous faisons de manière répétée. L'excellence n'est donc pas un acte, mais une habitude.", auteur: "Aristote", statut: "apocryphe",
    explication: "La phrase est de l'historien américain Will Durant, dans « The Story of Philosophy » (1926), qui résume l'« Éthique à Nicomaque » : il y met les mots d'Aristote entre guillemets, pas ceux-là. L'idée est bien d'Aristote : on devient vertueux en agissant vertueusement." },
];
